def main():
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Central Comparison Table"

    header_fill = PatternFill(start_color="2F5496", end_color="2F5496", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF", size=10)
    thin = Side(style="thin", color="BFBFBF")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    for c, name in enumerate(COLUMNS, start=1):
        cell = ws.cell(row=1, column=c, value=name)
        cell.font = header_font
        cell.fill = header_fill
        cell.alignment = Alignment(wrap_text=True, vertical="center", horizontal="center")
        cell.border = border
    ws.freeze_panes = "A2"
    ws.row_dimensions[1].height = 32

    widths = [12, 34, 26, 18, 20, 30, 10, 42, 12, 30, 30, 26, 46]
    for c, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(c)].width = w

    prev_group = None
    for r, row in enumerate(PUBLIC_ROWS, start=2):
        is_new_group = row[0] != prev_group
        prev_group = row[0]
        for c, val in enumerate(row, start=1):
            cell = ws.cell(row=r, column=c, value=val)
            cell.alignment = Alignment(wrap_text=True, vertical="top")
            cell.border = border
            if is_new_group and c == 1:
                cell.font = Font(bold=True)
        ws.row_dimensions[r].height = 45

    ws.auto_filter.ref = f"A1:{get_column_letter(len(COLUMNS))}{len(PUBLIC_ROWS)+1}"

    notes = wb.create_sheet("Notes")
    notes["A1"] = "Central Comparison Table — compilation notes"
    notes["A1"].font = Font(bold=True, size=13)
    notes_text = [
        "",
        "One row per species x method x reference. Every numeric value was either recomputed directly",
        "from a study's raw/deposited data, or extracted from the study's own reported text/tables --",
        "see the 'Reference' column for the source and the 'Notes / caveats' column for how each value",
        "was derived. This table is used to build Figure 1.",
        "",
        "Methodological caveats that apply ACROSS multiple rows:",
        "  - cM/Mb from LD-based, pedigree-based, and cytogenetic methods are not the same quantity.",
        "    Several LD-based cM/Mb values in this table are normalized/calibrated to match an assumed",
        "    or borrowed genetic map length rather than an independent measurement -- flagged per row.",
        "  - Gini values in this table are computed raw/unbinned as a deliberate standard across all",
        "    studies here, for reproducibility and cross-study consistency, rather than to match each",
        "    paper's own published Gini exactly. Where a paper reports its own Gini, our raw/unbinned",
        "    recompute runs higher than their published value by construction -- not an error.",
        "  - Gini computed from pyrho output is not directly comparable to Gini computed from",
        "    LDhat/LDhelmet output, even at matched raw/unbinned resolution -- pyrho's block-penalty",
        "    smoothing produces mechanically smoother maps.",
        "  - Cross-species physical-genome-length substitution (using a congener's assembly when a",
        "    study's own species has no chromosome-level assembly) is used for several cytogenetic rows",
        "    where noted -- flagged per row.",
        "",
        "Known gaps (not computable, and not forced):",
        "  - Cytogenetic (MLH1 foci / chiasma count) and older microsatellite linkage-map studies cannot",
        "    yield fine-scale cM/Mb maps, Gini, or NCO rates -- a method limitation, not a data-access",
        "    failure. Genome-wide cM/Mb is still computable for these via the 1-focus/chiasma=50cM",
        "    convention combined with a physical genome length.",
        "  - Long-read testis/sperm counts (Porsborg et al. 2025) are raw event counts, not rate-",
        "    normalized -- a genuine per-bp per-generation rate would require raw sequencing coverage",
        "    reprocessing, out of scope for this review.",
        "  - Several pedigree NCO counts have no stated per-site rate in the source paper's main text.",
    ]
    for i, line in enumerate(notes_text, start=2):
        notes.cell(row=i, column=1, value=line)
    notes.column_dimensions["A"].width = 100

    out_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "Central_Comparison_Table.xlsx")
    wb.save(out_path)
    print(f"Wrote {out_path} with {len(PUBLIC_ROWS)} data rows")


if __name__ == "__main__":
    main()
